import { useState } from "react";
import Calculation from '../Calculation/Calculation'

import "./BtnCal.css";

function BtnCal() {
  const [show, setShow] = useState(false);
  function showHide() {
    setShow(!show);
  }

  return (
    <div>
      <button className="btnCal" onClick={showHide}>Calculation</button>
      {show }
    </div>
  );
}

export default BtnCal;
